#!/usr/bin/env python3
"""mt4 stage A: lists the functions of the generated C (the wsrc of a lift: src/fle-*.c and v-*/src/m*.c) that contain an atomic read-modify-write of the guest (fle_cas, fle_xchg, fle_xadd, fle_cmpxchg16b: what fe-lift emits for the LOCK-prefixed
and the implicitly locked instructions, runtime/fle_rmw.h). fe-wasmgen leaves such a function on the C path, so a hybrid function list must not name it (lift/harness/hyb/filter-hybrid-list.py removes them). Output (stdout): TSV `va<TAB>sites<TAB>mnemonics`, the
mnemonic from the `/* 0xVA Mnemonic */` comment of the line. A lift that differs (another module set: Elastique, oggio) needs its own list.
usage: list-atomic-functions.py WSRC_DIR > seeds/mt4-atomic-functions.tsv

The lists and their roles (decisions 0246 and 0243): seeds/mt4-atomic-functions.tsv is the list of the lift of the SIX modules of HEAD (FLEngine, dsp_ippv2, Blend2D, QuickFontCache, FreeType, ILTools: 440 functions);
seeds/mt4-atomic-functions-m67.tsv holds only the rows that the lift of the EIGHT modules adds (oggio 0xc000000, Elastique 0xb000000: 60 functions). Run this script over the wsrc of a lift BEFORE the strip step of the wasm stage (the strip
takes the bodies of the hybrid functions out of wsrc in place, and a stripped function is not seen). A new module needs its own rows: make them with this script over the lift of all modules and keep the rows the older lists do not have;
then run filter-hybrid-list.py with them over the lists of that module. If a listed function is missing, the hybn0 stage says so and names the reason (a status "atomic read-modify-write stays on the C path" means: this list is incomplete)."""
import sys, re, glob, collections
fn = re.compile(r'^void (f_[0-9a-f]+)\(void\)\s*$')
tok = re.compile(r'\b(fle_cas|fle_xchg|fle_xadd|fle_cmpxchg16b)\(')
mn = re.compile(r'/\* 0x[0-9a-f]+ (\w+) \*/')
funcs = collections.OrderedDict(); cur = None
for p in sorted(glob.glob(sys.argv[1] + '/**/*.c', recursive=True)):
    for l in open(p, errors='replace'):
        m = fn.match(l.rstrip('\n'))
        if m: cur = m.group(1); continue
        if cur and tok.search(l):
            m = mn.search(l)
            funcs.setdefault(cur, collections.Counter())[m.group(1) if m else '?'] += 1
print('# mt4 stage A: the functions of the lift that contain a LOCK-prefixed or implicitly locked instruction (an atomic read-modify-write: fle_cas / fle_xchg / fle_xadd / fle_cmpxchg16b in the generated C). fe-wasmgen does not lower them, so a hybrid list must not name them (reason: contains a LOCK-prefixed or implicitly locked instruction, stays on the C path). Generated by lift/harness/hyb/list-atomic-functions.py from the lift of the F2xH7 input (FLEngine_x64.dll build 5653 and its modules, no Elastique / oggio).')
print('va\tsites\tmnemonics')
for f, c in sorted(funcs.items(), key=lambda kv: int(kv[0][2:], 16)):
    print('%#x\t%d\t%s' % (int(f[2:], 16), sum(c.values()), ' '.join('%s:%d' % kv for kv in sorted(c.items()))))
